function PreviewHero({ loadout }: { loadout: EquipmentLoadout }) {
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  const tint = useMemo(() => {
    if (loadout.armor === 'graveplate') return '#3b3b43'
    if (loadout.armor === 'veilweave-coat') return '#ededf1'
    return '#777780'
  }, [loadout.armor])
  const charmColor =
    loadout.charm === 'watcher-lens'
      ? '#ffffff'
      : loadout.charm === 'shattered-hourglass'
        ? '#d4143b'
        : '#a6a6ae'

  return (
    <group position={[-1.15, 0, 0.35]} rotation={[0, 0, 0]}>
      <AssetBoundary
        fallback={<PreviewFallback tint={tint} />}
        resetKey="lobby-hero"
      >
        <AnimatedCharacterModel
          name="lobby-hero"
          url={assetUrl('models/hero.glb')}
          motionRef={motionRef}
          position={[0, 0.02, 0]}
          rotation={[0, 0, 0]}
          scale={0.84}
          tint={tint}
          tintStrength={0.3}
          castShadow
        />
      </AssetBoundary>
      <mesh position={[0, 1.52, -0.22]}>
        <torusGeometry args={[0.34, 0.018, 8, 36]} />
        <meshToonMaterial
          color={charmColor}
          emissive={charmColor}
          emissiveIntensity={2.1}
          gradientMap={toonGradientMap}
        />
      </mesh>
    </group>
  )
}

function FrozenLobbyEnemy({
  position,
  rotation,
  model,
  weapon = 'sword',
  scale = 0.48,
}: {
  position: [number, number, number]
  rotation: [number, number, number]
  model: 'skeleton-base' | 'skeleton-archer' | 'skeleton-warrior'
  weapon?: 'sword' | 'crossbow'
  scale?: number
}) {
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })

  return (
    <AssetBoundary
      fallback={null}
      resetKey={`lobby-${model}-${position.join('-')}`}
    >
      <AnimatedCharacterModel
        name="lobby-frozen-enemy"
        url={assetUrl(`models/${model}.glb`)}
        motionRef={motionRef}
        skeleton
        paused
        frozen
        position={position}
        rotation={rotation}
        scale={scale}
        tint="#d4143b"
        tintStrength={1}
        castShadow
        attachments={[
          { url: assetUrl(`models/weapons/${weapon}.glb`), scale: 0.92 },
        ]}
      />
    </AssetBoundary>
  )
}

function DungeonProp({
  asset,
  position,
  rotation = [0, 0, 0],
  scale = 1,
  tint = '#55555e',
}: {
  asset: string
  position: [number, number, number]
  rotation?: [number, number, number]
  scale?: number | [number, number, number]
  tint?: string
}) {
  return (
    <AssetBoundary
      fallback={null}
      resetKey={`lobby-prop-${asset}-${position.join('-')}`}
    >
      <StaticGltfModel
        url={assetUrl(asset)}
        position={position}
        rotation={rotation}
        scale={scale}
        tint={tint}
        tintStrength={0.36}
        outline
      />
    </AssetBoundary>
  )
}

