export function LobbyPreview({ loadout }: { loadout: EquipmentLoadout }) {
  return (
    <div className="boda-lobby-render" data-testid="lobby-render">
      <Canvas
        shadows="percentage"
        dpr={[1, 1.35]}
        camera={{ position: [-0.75, 2.65, 7.2], fov: 38, near: 0.1, far: 30 }}
        gl={{
          antialias: true,
          powerPreference: 'high-performance',
          alpha: false,
        }}
        onCreated={({ camera, gl }) => {
          gl.outputColorSpace = SRGBColorSpace
          gl.toneMapping = NeutralToneMapping
          gl.toneMappingExposure = 1.14
          camera.lookAt(-0.75, 1.12, -0.35)
        }}
      >
        <Suspense fallback={null}>
          <PreviewScene loadout={loadout} />
        </Suspense>
      </Canvas>
    </div>
  )
}
